<script setup>
import { computed, ref } from 'vue';
import { ArrowLeft, Eye, Pencil, XCircle } from 'lucide-vue-next';
import { useRoute, useRouter } from 'vue-router';
import { useAuthStore } from '@/stores/auth';
import { useInvoiceStore } from '@/stores/invoice';
import { useUiStore } from '@/stores/ui';
import { masterDataConfig } from '@/data/masterDataMock';
import { formatCurrency, formatDate } from '@/utils/formatters';
import BaseBadge from '@/components/ui/BaseBadge.vue'; import BaseButton from '@/components/ui/BaseButton.vue'; import BaseCard from '@/components/ui/BaseCard.vue'; import ConfirmDialog from '@/components/ui/ConfirmDialog.vue';
const route=useRoute(),router=useRouter(),auth=useAuthStore(),store=useInvoiceStore(),ui=useUiStore(),confirm=ref(false); const invoice=computed(()=>store.getInvoiceById(route.params.id)); const readOnly=computed(()=>auth.role==='manager'); const total=computed(()=>invoice.value?.items.reduce((sum,item)=>sum+item.price*item.qty,0)-(invoice.value?.discount||0)); const account=computed(()=>masterDataConfig.account.records.find(x=>x.id===invoice.value?.accountId)); const docBadge=s=>({draft:['Draft','default'],published:['Diterbitkan','info'],cancelled:['Dibatalkan','danger']}[s]); const payBadge=s=>({belum_dibayar:['Belum Dibayar','neutral'],dibayar_sebagian:['Dibayar Sebagian','warning'],lunas:['Lunas','success'],jatuh_tempo:['Jatuh Tempo','danger']}[s]); const cancel=()=>{store.cancelInvoice(invoice.value.id);ui.notify('Invoice berhasil dibatalkan.');confirm.value=false};
</script>
<template><div v-if="invoice" class="p-6"><header class="mb-5 flex items-start justify-between gap-4"><div class="flex gap-3"><button class="mt-0.5 rounded p-1 text-[#667085] hover:bg-[#F5F7FA]" aria-label="Kembali ke invoice" @click="router.push({name:'invoice'})"><ArrowLeft :size="18"/></button><div><h1 class="text-xl font-semibold text-[#172033]">{{invoice.number}}</h1><p class="mt-0.5 text-sm text-[#667085]">{{invoice.name}}</p></div></div><div class="flex flex-wrap justify-end gap-2"><BaseButton variant="secondary" @click="router.push({name:'invoice-preview',params:{id:invoice.id}})"><Eye :size="15"/>Preview</BaseButton><BaseButton v-if="!readOnly&&invoice.status!=='cancelled'" variant="secondary" @click="router.push({name:'invoice-edit',params:{id:invoice.id}})"><Pencil :size="15"/>Edit</BaseButton><BaseButton v-if="!readOnly&&invoice.status!=='cancelled'" variant="danger" @click="confirm=true"><XCircle :size="15"/>Batalkan</BaseButton></div></header><div class="grid gap-5 xl:grid-cols-3"><div class="space-y-5 xl:col-span-2"><BaseCard padding="p-5"><div class="mb-5 flex flex-wrap items-center justify-between gap-3"><div><h2 class="text-[15px] font-semibold text-[#172033]">Informasi Invoice</h2><p class="mt-1 text-sm text-[#667085]">{{invoice.client}}</p></div><div class="flex gap-2"><BaseBadge :variant="docBadge(invoice.status)[1]">{{docBadge(invoice.status)[0]}}</BaseBadge><BaseBadge :variant="payBadge(invoice.paymentStatus)[1]">{{payBadge(invoice.paymentStatus)[0]}}</BaseBadge></div></div><dl class="grid gap-4 text-sm sm:grid-cols-3"><div><dt class="text-[#667085]">Tanggal Invoice</dt><dd class="mt-1 font-medium text-[#172033]">{{formatDate(invoice.date)}}</dd></div><div><dt class="text-[#667085]">Jatuh Tempo</dt><dd class="mt-1 font-medium text-[#172033]">{{formatDate(invoice.dueDate)}}</dd></div><div><dt class="text-[#667085]">Rekening Penerima</dt><dd class="mt-1 font-medium text-[#172033]">{{account?.nama||'-'}}</dd></div></dl></BaseCard><BaseCard padding="p-0"><div class="border-b border-[#E2E6EC] px-5 py-4"><h2 class="text-[15px] font-semibold text-[#172033]">Rincian Item</h2></div><div class="overflow-x-auto"><table class="w-full min-w-[620px]"><thead class="bg-[#F9FAFB]"><tr><th v-for="h in ['Produk / Layanan','Deskripsi','Harga','Qty','Total']" :key="h" class="px-5 py-3 text-left text-xs font-medium text-[#667085] last:text-right">{{h}}</th></tr></thead><tbody><tr v-for="item in invoice.items" :key="item.id" class="border-t border-[#F0F2F5]"><td class="px-5 py-3.5 text-sm font-medium text-[#172033]">{{item.product||'-'}}</td><td class="px-5 py-3.5 text-sm text-[#667085]">{{item.description}}</td><td class="px-5 py-3.5 text-sm text-[#667085]">{{formatCurrency(item.price)}}</td><td class="px-5 py-3.5 text-sm text-[#667085]">{{item.qty}}</td><td class="px-5 py-3.5 text-right text-sm font-medium text-[#172033]">{{formatCurrency(item.price*item.qty)}}</td></tr></tbody></table></div></BaseCard><BaseCard v-if="invoice.terms||invoice.notes" padding="p-5"><div v-if="invoice.terms"><h2 class="text-[15px] font-semibold text-[#172033]">Syarat & Ketentuan</h2><p class="mt-2 whitespace-pre-line text-sm leading-6 text-[#667085]">{{invoice.terms}}</p></div><div v-if="invoice.notes" :class="invoice.terms&&'mt-5'"><h2 class="text-[15px] font-semibold text-[#172033]">Catatan</h2><p class="mt-2 whitespace-pre-line text-sm leading-6 text-[#667085]">{{invoice.notes}}</p></div></BaseCard></div><aside><BaseCard padding="p-5" class="xl:sticky xl:top-6"><h2 class="mb-4 text-[15px] font-semibold text-[#172033]">Ringkasan Pembayaran</h2><div class="space-y-3 border-b border-[#E2E6EC] pb-4 text-sm"><div class="flex justify-between text-[#667085]"><span>Subtotal</span><span>{{formatCurrency(total+invoice.discount)}}</span></div><div class="flex justify-between text-[#667085]"><span>Diskon</span><span>{{formatCurrency(invoice.discount)}}</span></div></div><div class="mt-4 flex justify-between"><span class="text-sm font-medium text-[#172033]">Total Tagihan</span><strong class="text-lg text-[#173B6C]">{{formatCurrency(total)}}</strong></div><div class="mt-5 border-t border-[#E2E6EC] pt-4 text-sm"><p class="text-[#667085]">Pembayaran diterima</p><p class="mt-1 text-base font-semibold text-[#172033]">{{invoice.paymentStatus==='lunas'?formatCurrency(total):invoice.paymentStatus==='dibayar_sebagian'?formatCurrency(total/2):formatCurrency(0)}}</p><p class="mt-3 text-[#667085]">Sisa tagihan</p><p class="mt-1 text-base font-semibold text-[#172033]">{{invoice.paymentStatus==='lunas'?formatCurrency(0):invoice.paymentStatus==='dibayar_sebagian'?formatCurrency(total/2):formatCurrency(total)}}</p></div></BaseCard></aside></div><ConfirmDialog :open="confirm" title="Batalkan Invoice" message="Invoice akan tetap tersimpan sebagai riwayat." confirm-label="Batalkan" danger @cancel="confirm=false" @confirm="cancel"/></div><div v-else class="p-6 text-sm text-[#667085]">Invoice tidak ditemukan.</div></template>
